program = '''def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    moves = {1: (-1, 2), 2: (0, -4), 3: (3, 0), 6: (-6, 0)}
    paths = []

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color not in moves:
                continue
            dr, dc = moves[color]
            path = [(r, c)]
            if dr == -1 and dc == 2:
                # These motions bend horizontally first, then vertically.
                path.extend([(r, c + 1), (r, c + 2), (r - 1, c + 2)])
            else:
                steps = max(abs(dr), abs(dc))
                sr = 0 if dr == 0 else (1 if dr > 0 else -1)
                sc = 0 if dc == 0 else (1 if dc > 0 else -1)
                path.extend((r + sr * i, c + sc * i) for i in range(1, steps + 1))
            paths.append((color, path))
            for pr, pc in path[1:-1]:
                if 0 <= pr < h and 0 <= pc < w:
                    out[pr][pc] = 5

    crossings = set()
    for i in range(len(paths)):
        for j in range(i + 1, len(paths)):
            a, b = set(paths[i][1]), set(paths[j][1])
            crossings.update(a & b)

    for r, c in crossings:
        out[r][c] = 4
        rr, cc = r + 1, c - 1
        while 0 <= rr < h and 0 <= cc < w:
            out[rr][cc] = 4
            rr += 1
            cc -= 1

    return out
'''
